const data = $input.first().json;
const stats = data.chroma_db_stats || {};
const total = data.total_chunks || 0;
const MIN_CHUNKS_PER_EXAM = 50;

const alerts = [];
const healthy = [];

for (const [exam, count] of Object.entries(stats)) {
  if (count < MIN_CHUNKS_PER_EXAM) {
    alerts.push({ exam, count, issue: count === 0 ? 'EMPTY' : 'BELOW_THRESHOLD' });
  } else {
    healthy.push({ exam, count });
  }
}

return [{
  json: {
    total_chunks: total,
    index_status: data.status,
    alerts,
    healthy,
    has_alerts: alerts.length > 0,
    checked_at: new Date().toISOString()
  }
}];

const data = $input.first().json;
const alertSummary = data.alerts.map(a => '  - ' + a.exam + ': ' + a.count + ' chunks (' + a.issue + ')').join('
');
const message = '[CertMasterAI] RAG Quality Alert

The following exams have insufficient ChromaDB coverage:
' + alertSummary + '

Total chunks: ' + data.total_chunks + '
Checked at: ' + data.checked_at + '

Action: Auto re-index triggered for failing exams only.';
console.warn(message);
return [{ json: { alert: true, message, alerts: data.alerts, total_chunks: data.total_chunks, checked_at: data.checked_at } }];

// FIX: Extract only the failing exams and return one item per exam.
// Previously this node re-indexed ALL exams even when only 1 failed.
const data = $input.first().json;
return data.alerts.map(a => ({ json: { exam_code: a.exam, issue: a.issue, count: a.count } }));

// FIX: Added result check — was completely missing before.
const result = $input.first().json;
let exam;
try {
  exam = $('Re-index One at a Time').first().json.exam_code;
} catch (e) {
  exam = 'UNKNOWN';
}
const r = (result.results && result.results[exam]) || {};

if (r.status === 'success') {
  console.log('[WF4 Auto-fix] ' + exam + ': SUCCESS — ' + (r.chunks_indexed || 0) + ' chunks');
} else {
  console.error('[WF4 Auto-fix] ' + exam + ': FAILED — ' + (r.reason || 'check if data/scraped/' + exam.toLowerCase() + '/ has .txt files'));
}

return [{ json: { exam_code: exam, status: r.status || 'failed', chunks_indexed: r.chunks_indexed || 0, reason: r.reason || null } }];

const data = $input.first().json;
console.log('[CertMasterAI] Quality check PASSED — ' + data.total_chunks + ' total chunks across ' + data.healthy.length + ' exams.');
return [{ json: { alert: false, status: 'healthy', total_chunks: data.total_chunks } }];
